import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"支持范围调整与实用性注意事项","description":"根据Azure、PLaMo和TranslateGemma实测输出，说明支持语言和翻译质量注意事项。","frontmatter":{"description":"根据Azure、PLaMo和TranslateGemma实测输出，说明支持语言和翻译质量注意事项。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/translation/review"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"支持范围调整与实用性注意事项 | Mutelink"}],["meta",{"property":"og:description","content":"根据Azure、PLaMo和TranslateGemma实测输出，说明支持语言和翻译质量注意事项。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/compare/translation/review"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"支持范围调整与实用性注意事项 | Mutelink"}],["meta",{"name":"twitter:description","content":"根据Azure、PLaMo和TranslateGemma实测输出，说明支持语言和翻译质量注意事项。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}]]},"headers":[],"relativePath":"zh/compare/translation/review.md","filePath":"zh/compare/translation/review.md"}'),o={name:"zh/compare/translation/review.md"};function i(d,t,l,h,s,m){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="対応表の見直しと、実用性の注意" tabindex="-1">支持范围调整与实用性注意事项 <a class="header-anchor" href="#対応表の見直しと、実用性の注意" aria-label="Permalink to &quot;支持范围调整与实用性注意事项 {#対応表の見直しと、実用性の注意}&quot;">​</a></h1><p><a href="./../translation">对比一览</a></p><h2 id="判断の範囲" tabindex="-1">判断范围 <a class="header-anchor" href="#判断の範囲" aria-label="Permalink to &quot;判断范围 {#判断の範囲}&quot;">​</a></h2><p>5,040次请求均成功并返回非空文本，但请求成功不保证语言支持或翻译质量。以下决定仅针对能否按指定语言生成，并非母语者已确认全部含义与自然度。各语言页保留全部原始输出。</p><h2 id="translategemmaで復帰する3言語" tabindex="-1">TranslateGemma恢复的3种语言 <a class="header-anchor" href="#translategemmaで復帰する3言語" aria-label="Permalink to &quot;TranslateGemma恢复的3种语言 {#translategemmaで復帰する3言語}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>EN→X chrF</th><th>X→EN chrF</th><th>观察与判断</th></tr></thead><tbody><tr><td><a href="./zh-hant">繁体中文</a></td><td>46.2</td><td>71.5</td><td>双向30/30。英语→繁体中文的30句未混入代表性的简体特有字，确认遵循指定字形。</td></tr><tr><td><a href="./ms">马来语</a></td><td>67.2</td><td>72.6</td><td>双向30/30，模型模板也有ms。因可生成指定语言而恢复，但存在含义颠倒案例。</td></tr><tr><td><a href="./tl">菲律宾语</a></td><td>58.2</td><td>71.5</td><td>双向30/30，模板中有tl。因可生成指定语言而恢复，但存在VR用语误译。</td></tr></tbody></table><h3 id="品質上の注意例" tabindex="-1">需注意的质量问题 <a class="header-anchor" href="#品質上の注意例" aria-label="Permalink to &quot;需注意的质量问题 {#品質上の注意例}&quot;">​</a></h3><ul><li>Gemma马来语EN→X #10：“麦克风坏了”被译为<code>Mikrofon saya berfungsi dengan baik</code>（麦克风运作正常），核心含义颠倒。虽能生成马来语，重要内容仍须核对。</li><li>Gemma菲律宾语X→EN #9：进入VRChat实例被译为<code>Now, I want to discuss this specific case with you.</code>，变成讨论案例。</li><li>测量的是<strong>TranslateGemma 4B Q4_K_M</strong>而非Gemini，以及<strong>PLaMo 0.8B Q4_K_M</strong>，不可推广到其他尺寸。</li></ul><h2 id="plamoで除外を維持する9言語" tabindex="-1">PLaMo继续排除的9种语言 <a class="header-anchor" href="#plamoで除外を維持する9言語" aria-label="Permalink to &quot;PLaMo继续排除的9种语言 {#plamoで除外を維持する9言語}&quot;">​</a></h2><p>对官方53语言列表之外的语言，也绕过应用白名单各直接测试60次。因正向出现其他语言或混合语言，反向出现原文照抄等，继续从该模型选项中排除。并非仅因chrF低而排除。</p><table tabindex="0"><thead><tr><th>语言</th><th>EN→X chrF</th><th>X→EN未翻译照抄数/30</th><th>EN→X #1实际输出（成功不代表指定语言）</th></tr></thead><tbody><tr><td><a href="./pt">pt</a></td><td>15.2</td><td>8/30</td><td>Hallo, a拾って好上好。</td></tr><tr><td><a href="./tr">tr</a></td><td>3.1</td><td>4/30</td><td>Hallo, சிறப்பாக அறிமுகமாகிறேன்.</td></tr><tr><td><a href="./sv">sv</a></td><td>15.6</td><td>8/30</td><td>Hallo, leuk om you kennis te maken.</td></tr><tr><td><a href="./da">da</a></td><td>1.8</td><td>19/30</td><td>नमस्ते, खुशी लाग्यो भेट भएकोमा।</td></tr><tr><td><a href="./fi">fi</a></td><td>11.5</td><td>10/30</td><td>Hallo, freundlich kennenzulernen.</td></tr><tr><td><a href="./cs">cs</a></td><td>11.0</td><td>0/30</td><td>Hallo, leuk je jeter.</td></tr><tr><td><a href="./el">el</a></td><td>2.2</td><td>10/30</td><td>Hallo, leuke jeter.</td></tr><tr><td><a href="./ro">ro</a></td><td>3.0</td><td>13/30</td><td>नमस्ते, खुश लինուँ भेटेकोमा।</td></tr><tr><td><a href="./uk">uk</a></td><td>18.8</td><td>0/30</td><td>Hallo, приятно познакомиться.</td></tr></tbody></table><p>PLaMo保持原有19种语言加英语（共20种），Azure保持本次全部28种，TranslateGemma可选择全部28种加英语。质量应在同一语言和方向内比较，不可用不同语言的chrF直接排名。</p><h2 id="検証データの由来" tabindex="-1">验证数据来源 <a class="header-anchor" href="#検証データの由来" aria-label="Permalink to &quot;验证数据来源 {#検証データの由来}&quot;">​</a></h2><p>原有26种语言参考文由Claude生成，新增繁体中文和菲律宾语由Codex生成，均未经母语者校对。提供全部输出以便不只依赖数值或“实验性”标签判断。发布后的母语者评审应另加注释，不改写原始输出。</p>',14)])])}const p=e(o,[["render",i]]);export{c as __pageData,p as default};
